def parse_amount(val_str):
    if not val_str:
        return Decimal('0.00')
    cleaned = re.sub(r'[^\d\.]', '', str(val_str).strip())
    if not cleaned:
        return Decimal('0.00')
    try:
        return Decimal(cleaned)
    except:
        return Decimal('0.00')

def get_or_create_category(cat_raw, type_raw=""):
    cat_raw = (cat_raw or '').strip().upper()
    type_raw = (type_raw or '').strip().upper()
    
    name_map = {
        'POWER': 'Power',
        'CONSTRUCTION': 'Construction',
        'CONSTRUCTION/SUPPLY': 'Construction',
        'SUPPLY\\EMPOWERMENT': 'Supply',
        'SUPPLY/EMPOWERMENT': 'Supply',
        'TRAINING': 'Training',
        'SUPPLY': 'Supply',
        'EMPOWERMENT': 'Empowerment',
        'CONSTRUCTION/SUPPLY': 'Construction',
    }
    
    cat_name = name_map.get(cat_raw)
    if not cat_name:
        if 'CONSTRUCTION' in cat_raw or 'CONSTRUCTION' in type_raw:
            cat_name = 'Construction'
        elif 'POWER' in cat_raw or 'POWER' in type_raw:
            cat_name = 'Power'
        elif 'TRAINING' in cat_raw or 'TRAINING' in type_raw:
            cat_name = 'Training'
        elif 'EMPOWERMENT' in cat_raw or 'EMPOWERMENT' in type_raw:
            cat_name = 'Empowerment'
        else:
            cat_name = 'Supply'
            
    cat_obj, _ = ProjectCategory.objects.get_or_create(name=cat_name, defaults={'description': f'{cat_name} Projects'})
    return cat_obj

def get_project_type(cat_raw, type_raw=""):
    comb = (cat_raw + ' ' + type_raw).upper()
    if 'CONSTRUCTION' in comb or 'CIVIL' in comb or 'WORKS' in comb:
        return 'CONSTRUCTION'
    return 'SUPPLY_TRAINING'

def parse_prompt_rows():
    lines = PROMPT_RAW_DATA.strip().split('\n')
    parsed_rows = []
    current_row = None

    for line in lines:
        if not line.strip():
            continue
        parts = line.split('\t')
        if parts[0].strip().isdigit() and len(parts) >= 4:
            if current_row:
                parsed_rows.append(current_row)
            current_row = parts
        else:
            if current_row:
                current_row[-1] += "\n" + line

    if current_row:
        parsed_rows.append(current_row)

    return parsed_rows

def import_2025_projects():
    # Fee types
    fee_facilitation, _ = FeeType.objects.get_or_create(name='Facilitation Fee (PR)', defaults={'description': 'Facilitation Fee (PR)'})
    fee_logistics, _ = FeeType.objects.get_or_create(name='Logistics and Monitoring', defaults={'description': 'Logistics and Monitoring Fee (10% of Contract Amount)'})

    # Users cache
    users_cache = {}
    for u in User.objects.all():
        users_cache[u.username.upper()] = u

    # 2025 Timestamp
    dt_2025 = datetime.datetime(2025, 6, 1, 12, 0, 0, tzinfo=datetime.timezone.utc)

    parsed_rows = parse_prompt_rows()
    print(f"Total parsed rows from prompt table: {len(parsed_rows)}", flush=True)

    # Excluded agencies: BCDA and NDE
    EXCLUDED_AGENCIES_KEYWORDS = [
        'BORDER COMMUNITIES DEVELOPMENT AGENCY',
        'BCDA',
        'NATIONAL DIRECTORATE OF EMPLOYMENT',
        'NDE'
    ]

    imported_count = 0
    skipped_count = 0

    with transaction.atomic():
        for row in parsed_rows:
            # Pad row to at least 45 fields
            while len(row) < 45:
                row.append('')

            sn_val = row[0].strip()
            mda = row[1].strip()
            project_code = row[2].strip()
            project_name = row[3].strip()
            plain_boq = row[4].strip()
            drawing_design = row[5].strip()
            type_str = row[6].strip()
            location = row[7].strip()
            category_raw = row[8].strip()
            award_letter_and_boq = row[9].strip()
            budget_amount = parse_amount(row[10])
            actual_contract_amount = parse_amount(row[11])
            admin_fee = parse_amount(row[12])
            facilitation_fee_raw = parse_amount(row[13])
            logistics_fee_raw = parse_amount(row[14])
            batch_no_mobilization = row[15].strip()
            mobilization_received = parse_amount(row[16])
            mob_date = row[17].strip()
            batch_no_final_payment = row[18].strip()
            amount_paid = parse_amount(row[19])
            in_house_benchmark = parse_amount(row[20])
            cost_percentage = parse_amount(row[21])
            staff_assigned_key = row[22].strip()
            subcontractor_raw = row[23].strip()
            
            sub_drawing = row[24].strip()
            sub_boq = row[25].strip()
            sub_cost_pct = parse_amount(row[26])
            sub_agreed_amt = parse_amount(row[27])
            sub_advance = parse_amount(row[28])
            sub_balance = parse_amount(row[29])

            completion_pct_raw = parse_amount(row[31])
            proj_status_raw = row[32].strip()
            payment_status_raw = row[33].strip()
            comments_raw = row[34].strip()
            lot = row[35].strip()
            final_companies = row[36].strip()
            back_up_companies = row[37].strip()
            updated_recommended_companies = row[38].strip()
            project_picture = row[39].strip()
            technical = row[40].strip()
            financials = row[41].strip()
            remarks = row[42].strip()

            # Check if agency is BCDA or NDE
            mda_upper = mda.upper()
            is_excluded = any(kw in mda_upper for kw in EXCLUDED_AGENCIES_KEYWORDS)

            if is_excluded:
                print(f"Skipping row {sn_val} ({mda} - {project_code}) because it belongs to excluded agency.", flush=True)
                skipped_count += 1
                continue

            category_obj = get_or_create_category(category_raw, type_str)
            proj_type = get_project_type(category_raw, type_str)

            # Get or create staff user
            staff_obj = None
            if staff_assigned_key:
                clean_staff_key = staff_assigned_key.upper().split('/')[0].strip()
                if clean_staff_key in users_cache:
                    staff_obj = users_cache[clean_staff_key]
                else:
                    staff_obj, _ = User.objects.get_or_create(
                        username=clean_staff_key,
                        defaults={'first_name': clean_staff_key, 'is_staff': True}
                    )
                    users_cache[clean_staff_key] = staff_obj

            # Facilitation Fee
            fac_fee = facilitation_fee_raw if facilitation_fee_raw > 0 else Decimal('16000.00')

            # Logistics Fee (10% of actual contract amount if not specified)
            if logistics_fee_raw > 0:
                log_fee = logistics_fee_raw
            elif actual_contract_amount > 0:
                log_fee = actual_contract_amount * Decimal('0.10')
            else:
                log_fee = Decimal('0.00')

            # Build remarks text
            remarks_parts = []
            if plain_boq:
                remarks_parts.append(f"BOQ: {plain_boq}")
            if drawing_design:
                remarks_parts.append(f"Drawing: {drawing_design}")
            if award_letter_and_boq:
                remarks_parts.append(f"Award Letter: {award_letter_and_boq}")
            if comments_raw:
                remarks_parts.append(f"Comments: {comments_raw}")
            if remarks:
                remarks_parts.append(f"Remarks: {remarks}")
            if updated_recommended_companies:
                remarks_parts.append(f"Recommended Companies: {updated_recommended_companies}")
            
            full_remarks = "\n".join(remarks_parts)

            proj_status = proj_status_raw or ('Awarded' if actual_contract_amount > 0 else 'Initiated')
            pay_status = payment_status_raw or 'Pending'
            execution_pct = int(completion_pct_raw) if completion_pct_raw > 0 else 0

            mda = mda[:255]
            project_code = project_code[:100]
            project_name = project_name[:512]
            lot = lot[:50]
            location = location[:255]
            batch_no_mobilization = batch_no_mobilization[:100]
            batch_no_final_payment = batch_no_final_payment[:100]
            technical = technical[:100]
            financials = financials[:100]
            proj_status = proj_status[:100]
            pay_status = pay_status[:100]

            # Create project record specifically for 2025
            proj = Project.objects.create(
                mda=mda,
                project_code=project_code,
                project_name=project_name,
                lot=lot,
                project_type=proj_type,
                location=location or 'NIGER EAST',
                category=category_obj,
                budget_amount=budget_amount,
                actual_contract_amount=actual_contract_amount,
                in_house_benchmark=in_house_benchmark,
                cost_percentage=cost_percentage,
                mobilization_received=mobilization_received,
                batch_no_mobilization=batch_no_mobilization,
                batch_no_final_payment=batch_no_final_payment,
                final_payment_received=amount_paid,
                staff_assigned=staff_obj,
                execution_mode='SUBCONTRACTED' if (subcontractor_raw or final_companies) else 'SELF_EXECUTED',
                current_phase='POST_AWARD' if actual_contract_amount > 0 else 'PRE_AWARD',
                execution_level_percentage=execution_pct,
                project_status=proj_status,
                payment_status=pay_status,
                plain_boq=plain_boq,
                drawing_design=drawing_design,
                award_letter_and_boq=award_letter_and_boq,
                final_companies=final_companies,
                back_up_companies=back_up_companies,
                updated_recommended_companies=updated_recommended_companies,
                technical_status=technical,
                financial_status=financials,
                comments=comments_raw,
                remarks=full_remarks
            )

            # Set created_at to 2025 explicitly
            Project.objects.filter(pk=proj.pk).update(created_at=dt_2025)

            # Set Facilitation Fee
            ProjectFee.objects.update_or_create(
                project=proj,
                fee_type=fee_facilitation,
                defaults={'amount': fac_fee}
            )

            # Set Logistics Fee
            if log_fee > 0:
                ProjectFee.objects.update_or_create(
                    project=proj,
                    fee_type=fee_logistics,
                    defaults={'amount': log_fee}
                )

            # Set Subcontractor allocation if specified
            sub_name = subcontractor_raw or final_companies
            if sub_name:
                sub_clean = sub_name.split('\n')[0].strip()
                if len(sub_clean) > 255:
                    sub_clean = sub_clean[:255]
                if sub_clean:
                    sub_obj, _ = Subcontractor.objects.get_or_create(
                        name=sub_clean,
                        defaults={'company_type': 'EXTERNAL'}
                    )
                    ProjectAllocation.objects.get_or_create(
                        project=proj,
                        subcontractor=sub_obj,
                        defaults={
                            'sub_contractor_cost_percentage': sub_cost_pct,
                            'amount_agreed_with_supplier_contractor': sub_agreed_amt,
                            'advance_received_by_supplier_contractor': sub_advance,
                        }
                    )

            imported_count += 1

    print(f"Successfully processed prompt rows. Skipped: {skipped_count}, Imported for 2025: {imported_count}.", flush=True)

if __name__ == '__main__':
    import_2025_projects()
